// ==========================================
// Cequre Core Engine
// ==========================================
export type HeadersInitLike = Record<string, string> | Headers;
export type ClientHeaders = HeadersInitLike | (() => HeadersInitLike | Promise<HeadersInitLike>);

export interface CequreClientConfig {
  baseUrl?: string;
  token?: string;
  getToken?: () => string | null | Promise<string | null>;
  credentials?: "omit" | "same-origin" | "include";
  onResponse?: (response: SDKResponse<unknown>) => void | Promise<void>;
  headers?: ClientHeaders;
}

export interface SDKResponse<T> {
  data: T | null;
  error: CequreError | null;
  status: number;
  url: string;
  headers: Headers | Record<string, string>;
}

export class CequreCore {
  protected config: CequreClientConfig;

  constructor(config: CequreClientConfig = {}) {

    this.config = { ...config, baseUrl: (config.baseUrl || "").replace(/\/$/, "") };
  }

  withToken(token: string): CequreClient {
    const cloned = Object.create(Object.getPrototypeOf(this));
    cloned.config = { ...this.config, token };
    cloned._cache = {};
    return cloned;
  }

  withHeaders(headers: ClientHeaders): CequreClient {
    const cloned = Object.create(Object.getPrototypeOf(this));
    const prevHeaders = this.config.headers;
    let combinedHeaders: ClientHeaders;
    if (!prevHeaders) {
      combinedHeaders = headers;
    } else {
      combinedHeaders = async () => {
        const p = typeof prevHeaders === 'function' ? await prevHeaders() : prevHeaders;
        const n = typeof headers === 'function' ? await headers() : headers;
        const pObj: Record<string, string> = {};
        if (p instanceof Headers) {
          p.forEach((v, k) => { pObj[k] = v; });
        } else if (p && typeof p === 'object') {
          for (const [k, v] of Object.entries(p)) {
            if (v !== undefined && v !== null) pObj[k] = String(v);
          }
        }
        const nObj: Record<string, string> = {};
        if (n instanceof Headers) {
          n.forEach((v, k) => { nObj[k] = v; });
        } else if (n && typeof n === 'object') {
          for (const [k, v] of Object.entries(n)) {
            if (v !== undefined && v !== null) nObj[k] = String(v);
          }
        }
        return { ...pObj, ...nObj };
      };
    }
    cloned.config = { ...this.config, headers: combinedHeaders };
    cloned._cache = {};
    return cloned;
  }

  async buildUrl(path: string, queryParams: Record<string, any> = {}): Promise<string> {
    let url = `${this.config.baseUrl}${path}`;
    const token = await this.resolveToken();
    const params = new URLSearchParams();
    for (const [key, val] of Object.entries(queryParams)) {
      if (val !== undefined && val !== null) {
        params.append(key, String(val));
      }
    }
    if (token) params.set("token", token);
    const qs = params.toString();
    if (qs) url += (url.includes('?') ? '&' : '?') + qs;
    return url;
  }

  private async resolveToken(): Promise<string | null> {
    if (this.config.token) return this.config.token;
    if (this.config.getToken) {
      const t = await this.config.getToken();
      if (t) return t;
    }
    return null;
  }

  private async getAuthHeader(): Promise<string | null> {
    const t = await this.resolveToken();
    return t ? `Bearer ${t}` : null;
  }

  private async resolveHeaders(): Promise<Record<string, string>> {
    const resolved: Record<string, string> = {};
    if (!this.config.headers) return resolved;
    const raw = typeof this.config.headers === 'function'
      ? await this.config.headers()
      : this.config.headers;
    if (raw instanceof Headers) {
      raw.forEach((val, key) => {
        resolved[key] = val;
      });
    } else if (raw && typeof raw === 'object') {
      for (const [key, val] of Object.entries(raw)) {
        if (val !== undefined && val !== null) {
          resolved[key] = String(val);
        }
      }
    }
    return resolved;
  }

  private async fetchWithRetry(url: string, options: RequestInit, maxRetries = 2): Promise<Response> {
    let lastError: unknown;
    const method = (options.method || 'GET').toUpperCase();
    const isIdempotent = method === 'GET' || method === 'HEAD' || method === 'OPTIONS';
    const retries = isIdempotent ? maxRetries : 0;

    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        const res = await fetch(url, options);
        if (res.status >= 500 && res.status !== 501 && attempt < retries) {
          await new Promise(r => setTimeout(r, 1000 * 2 ** attempt));
          continue;
        }
        return res;
      } catch (err: any) {
        if (err?.name === 'AbortError') throw err;
        lastError = err;
        if (attempt < retries) {
          await new Promise(r => setTimeout(r, 1000 * 2 ** attempt));
          continue;
        }
      }
    }
    throw lastError;
  }

  async request<T>(
    method: string, 
    path: string, 
    data?: any, 
    customHeaders: Record<string, string> = {}, 
    signal?: AbortSignal
  ): Promise<SDKResponse<T>> {
    const clientHeaders = await this.resolveHeaders();
    const headers: Record<string, string> = { 
      'X-Cequre-CSRF': '1',
      ...clientHeaders,
      ...customHeaders 
    };
    const auth = await this.getAuthHeader();
    if (auth && !headers['Authorization']) headers['Authorization'] = auth;

    const options: RequestInit = {
      method,
      headers,
      credentials: this.config.credentials,
      signal
    };

    if (data) {
      const hasFiles = this.containsFiles(data);
      if (hasFiles) {
        const formData = new FormData();
        for (const key of Object.keys(data)) {
          const val = data[key];
          if (val == null) continue;
          if (val instanceof File || val instanceof Blob) {
            formData.append(key, val);
          } else if (typeof val === 'boolean') {
            formData.append(key, val ? 'true' : 'false');
          } else if (typeof val === 'object') {
            formData.append(key, JSON.stringify(val));
          } else {
            formData.append(key, String(val));
          }
        }
        options.body = formData;
      } else {
        headers['Content-Type'] = 'application/json';
        options.body = JSON.stringify(data);
      }
    }

    try {
      const res = await this.fetchWithRetry(`${this.config.baseUrl}${path}`, options);
      
      if (!res.ok) {
        let errData;
        const errText = await res.text();
        try { 
          errData = JSON.parse(errText); 
        } catch { 
          errData = {
            code: "SERVER_ERROR",
            message: errText || res.statusText || "Unknown server error",
            statusCode: res.status,
            timestamp: new Date().toISOString(),
            path
          };
        }
        
        const errorObject: CequreError = {
          code: errData?.code || "UNKNOWN_ERROR",
          message: errData?.message || (typeof errData?.error === "string" ? errData.error : "An unexpected error occurred"),
          statusCode: errData?.statusCode || res.status,
          timestamp: errData?.timestamp || new Date().toISOString(),
          path: errData?.path || path,
          stack: errData?.stack
        };

        const result = { data: null, error: errorObject, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      }
      
      if (res.status === 204 || res.headers.get('content-length') === '0') {
        const result = { data: undefined as unknown as T, error: null, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      }
      
      const contentType = res.headers.get('content-type') || '';
      if (!contentType.includes('application/json') && !contentType.includes('text/')) {
        const blob = await res.blob();
        const result = { data: blob as unknown as T, error: null, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      }

      const text = await res.text();
      
      if (!text) {
        const result = { data: undefined as unknown as T, error: null, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      }
      
      try {
        const result = { data: JSON.parse(text) as T, error: null, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      } catch {
        const result = { data: text as unknown as T, error: null, status: res.status, url: res.url || path, headers: res.headers };
        if (this.config.onResponse) await this.config.onResponse(result);
        return result;
      }
    } catch (error: any) {
      if (error?.name === 'AbortError') throw error;
      if (error instanceof Response) throw error;
      const networkError: CequreError = {
        code: "NETWORK_ERROR",
        message: error?.message || "Failed to connect to the server",
        statusCode: 0,
        timestamp: new Date().toISOString(),
        path
      };
      const result = { data: null as any, error: networkError, status: 0, url: path, headers: {} };
      if (this.config.onResponse) await this.config.onResponse(result);
      return result;
    }
  }

  private containsFiles(data: any): boolean {
    if (!data || typeof data !== 'object') return false;
    for (const key of Object.keys(data)) {
      if (data[key] instanceof File || data[key] instanceof Blob) return true;
    }
    return false;
  }

  async uploadLargeFile(file: File, options?: { chunkSize?: number, onProgress?: (percent: number) => void }): Promise<SDKResponse<UploadedFile>> {
    const prefix = "/api"; // The standard Cequre prefix
    const token = await this.resolveToken();
    const clientHeaders = await this.resolveHeaders();

    const headers = new Headers();
    headers.set("X-Cequre-CSRF", "1");
    for (const [k, v] of Object.entries(clientHeaders)) {
      headers.set(k, v);
    }
    headers.set("x-filename", file.name);
    headers.set("x-mimetype", file.type || "application/octet-stream");
    headers.set("x-size", String(file.size));
    if (token && !headers.has("Authorization")) headers.set("Authorization", `Bearer ${token}`);

    const res = await this.fetchWithRetry(`${this.config.baseUrl}${prefix}/uploads/stream`, {
      method: "POST",
      headers,
      body: file.stream ? file.stream() : file,
    });

    if (!res.ok) {
      const errText = await res.text().catch(() => "");
      return {
        data: null,
        error: { code: "UPLOAD_ERROR", message: errText || `Upload failed with status ${res.status}`, statusCode: res.status, timestamp: new Date().toISOString() },
        status: res.status,
        url: `${prefix}/uploads/stream`,
        headers: res.headers,
      };
    }

    // Read the response stream for NDJSON events (or direct JSON fallback)
    if (res.body) {
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (value) {
            buffer += decoder.decode(value, { stream: true });
            // Parse NDJSON lines
            const lines = buffer.split("\n");
            buffer = lines.pop() || "";
            for (const line of lines) {
              const trimmed = line.trim();
              if (!trimmed) continue;
              try {
                const event = JSON.parse(trimmed);
                if (event.type === "progress" && typeof event.percent === "number") {
                  options?.onProgress?.(event.percent);
                } else if (event.type === "complete" && event.file) {
                  return {
                    data: event.file,
                    error: null,
                    status: 200,
                    url: `${prefix}/uploads/stream`,
                    headers: res.headers,
                  };
                } else if (event.filename && event.url) {
                  return {
                    data: event,
                    error: null,
                    status: 200,
                    url: `${prefix}/uploads/stream`,
                    headers: res.headers,
                  };
                }
              } catch {}
            }
          }
        }

        // Check any trailing buffer
        if (buffer.trim()) {
          try {
            const event = JSON.parse(buffer.trim());
            if (event.type === "complete" && event.file) {
              return {
                data: event.file,
                error: null,
                status: 200,
                url: `${prefix}/uploads/stream`,
                headers: res.headers,
              };
            } else if (event.filename && event.url) {
              return {
                data: event,
                error: null,
                status: 200,
                url: `${prefix}/uploads/stream`,
                headers: res.headers,
              };
            }
          } catch {}
        }
      } finally {
        reader.releaseLock();
      }
    }

    return {
      data: null,
      error: { code: "UPLOAD_ERROR", message: "Invalid upload response", statusCode: 500, timestamp: new Date().toISOString() },
      status: 500,
      url: `${prefix}/uploads/stream`,
      headers: res.headers,
    };
  }

  async *streamRequest(method: string, path: string, data?: any, options?: RequestInit): AsyncGenerator<string, void, unknown> {
    const clientHeaders = await this.resolveHeaders();
    const headers = new Headers();
    headers.set('X-Cequre-CSRF', '1');
    for (const [k, v] of Object.entries(clientHeaders)) {
      headers.set(k, v);
    }
    if (options?.headers) {
      new Headers(options.headers).forEach((v, k) => headers.set(k, v));
    }
    const token = await this.resolveToken();
    if (token && !headers.has('Authorization')) {
      headers.set('Authorization', `Bearer ${token}`);
    }

    const fetchOptions: RequestInit = {
      ...options,
      method,
      headers
    };

    if (data !== undefined) {
      if (this.containsFiles(data)) {
        const formData = new FormData();
        for (const key of Object.keys(data)) {
          const val = data[key];
          if (val == null) continue;
          if (val instanceof File || val instanceof Blob) {
            formData.append(key, val);
          } else if (typeof val === 'boolean') {
            formData.append(key, val ? 'true' : 'false');
          } else if (typeof val === 'object') {
            formData.append(key, JSON.stringify(val));
          } else {
            formData.append(key, String(val));
          }
        }
        fetchOptions.body = formData;
      } else {
        headers.set('Content-Type', 'application/json');
        fetchOptions.body = JSON.stringify(data);
      }
    }

    const res = await this.fetchWithRetry(`${this.config.baseUrl}${path}`, fetchOptions);
    
    if (!res.ok) {
      let errText = await res.text().catch(() => "");
      throw new Error(`Stream request failed with status ${res.status}: ${errText}`);
    }

    if (!res.body) return;

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        if (value) {
          yield decoder.decode(value, { stream: true });
        }
      }
    } finally {
      reader.cancel().catch(() => {});
      reader.releaseLock();
    }
  }

  /**
   * @security
   * When EventSource is used in browser environments, the authentication token
   * is appended to the URL query string. In Node.js/Bun environments, Authorization headers are used.
   */
  async subscribeSSE(channelOrPath: string, onEvent: (event: any) => void): Promise<() => void> {
    const isPath = channelOrPath.startsWith("/");
    const path = isPath ? channelOrPath : `/api/sse?channel=${encodeURIComponent(channelOrPath)}`;
    let url = `${this.config.baseUrl}${path}`;
    const token = await this.resolveToken();
    if (token) {
      url += (url.includes('?') ? '&' : '?') + `token=${encodeURIComponent(token)}`;
    }
    
    if (typeof (globalThis as any).EventSource !== 'undefined') {
      const es = new (globalThis as any).EventSource(url);
      let retryCount = 0;
      const maxRetries = 5;
      
      es.onmessage = (e: { data: string }) => {
        retryCount = 0;
        try {
          const parsed = JSON.parse(e.data);
          if (parsed && typeof parsed === "object" && ("data" in parsed || "type" in parsed)) {
            onEvent(parsed);
          } else {
            onEvent({ type: "message", data: parsed });
          }
        } catch {}
      };
      
      es.onerror = (_e: any) => {
        retryCount++;
        if (retryCount >= maxRetries) {
          es.close();
          es.onmessage = null;
          es.onerror = null;
        }
      };
      
      return () => {
        es.close();
        es.onmessage = null;
        es.onerror = null;
      };
    }

    let manualClose = false;
    let abortController = new AbortController();
    let retryCount = 0;
    const maxRetries = 5;

    const connectFetch = async () => {
      if (manualClose) return;
      abortController = new AbortController();
      const clientHeaders = await this.resolveHeaders();
      const headers: Record<string, string> = { 
        Accept: "text/event-stream",
        ...clientHeaders,
      };
      if (token && !headers["Authorization"]) headers["Authorization"] = `Bearer ${token}`;

      try {
        const res = await fetch(url, { headers, signal: abortController.signal });
        if (!res.ok || !res.body) throw new Error(`SSE connect failed with status ${res.status}`);
        retryCount = 0;

        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";

        while (!manualClose) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          const blocks = buffer.split("\n\n");
          buffer = blocks.pop() || "";

          for (const block of blocks) {
            if (!block.trim()) continue;
            let eventData = "";
            let eventName = "";
            for (const line of block.split("\n")) {
              if (line.startsWith("data:")) {
                const dataPart = line.slice(5).trim();
                eventData += (eventData ? "\n" : "") + dataPart;
              } else if (line.startsWith("event:")) {
                eventName = line.slice(6).trim();
              }
            }
            if (eventName === "connected" || eventName === "ping") continue;
            if (eventData) {
              try {
                const parsed = JSON.parse(eventData);
                if (parsed && typeof parsed === "object" && ("data" in parsed || "type" in parsed)) {
                  onEvent(parsed);
                } else if (eventName) {
                  const parts = eventName.split(":");
                  const action = parts[1] || eventName;
                  onEvent({ event: eventName, type: action, action, data: parsed });
                } else {
                  onEvent({ data: parsed });
                }
              } catch {
                onEvent(eventData);
              }
            }
          }
        }
      } catch (err: any) {
        if (manualClose || err?.name === "AbortError") return;
        if (retryCount < maxRetries) {
          retryCount++;
          setTimeout(connectFetch, Math.min(1000 * 2 ** retryCount, 30000));
        }
      }
    };

    connectFetch();

    return () => {
      manualClose = true;
      try { abortController.abort(); } catch {}
    };
  }

  async subscribeWS(roomOrPath: string, onEvent: (event: any) => void): Promise<() => void> {
    const isPath = roomOrPath.startsWith("/");
    const wsPath = isPath ? roomOrPath : `/api/ws`;
    const room = isPath ? null : roomOrPath;
    const wsUrl = (this.config.baseUrl || "").replace(/^http/, 'ws') + wsPath;
    const token = await this.resolveToken();
    let ws: WebSocket;
    let retryCount = 0;
    const maxRetries = 5;
    let manualClose = false;

    const connect = () => {
      ws = new WebSocket(wsUrl);
      ws.onopen = () => {
        retryCount = 0;
        if (token) ws.send(JSON.stringify({ type: 'auth', token }));
        if (room) ws.send(JSON.stringify({ type: 'join', room }));
      };
      ws.onmessage = (e: { data: string }) => {
        try {
          const msg = JSON.parse(e.data);
          if (msg && typeof msg === 'object' && (msg.type === 'connected' || msg.type === 'joined' || msg.type === 'left' || msg.type === 'pong')) {
            return;
          }
          onEvent(msg);
        } catch {}
      };
      ws.onerror = () => { /* consumer observes via onclose */ };
      ws.onclose = () => {
        if (manualClose) return;
        if (retryCount < maxRetries) {
          retryCount++;
          setTimeout(connect, Math.min(1000 * 2 ** retryCount, 30000));
        }
      };
    };
    
    connect();
    
    return () => {
      manualClose = true;
      if (ws && ws.readyState === 1 && room) {
        try { ws.send(JSON.stringify({ type: 'leave', room })); } catch {}
      }
      ws?.close();
      if (ws) {
        ws.onopen = null;
        ws.onmessage = null;
        ws.onerror = null;
        ws.onclose = null;
      }
    };
  }
}

export interface CequreRealtimeConfig extends CequreClientConfig {
  transport?: "ws" | "sse";
  autoCatchUp?: boolean;
}

export interface LiveQuerySubscription<T = unknown> {
  queryKey: string;
  collection: string;
  params?: any;
  data: T[];
  listeners: Set<(data: T[]) => void>;
  initialized: boolean;
  pendingPromise?: Promise<T[]>;
  lastEventId?: string;
}

export class CequreRealtimeCore {
  public client: CequreClient;
  protected config: CequreRealtimeConfig;
  protected prefix: string = "/api";
  private _subscriptions: Map<string, LiveQuerySubscription<any>> = new Map();
  private _activeChannels: Map<string, { count: number; unsubscribe: () => void }> = new Map();

  constructor(config: CequreRealtimeConfig = {}) {
    this.config = {
      ...config,
      transport: config.transport || "ws",
      autoCatchUp: config.autoCatchUp !== false,
    };
    this.client = new CequreClient(this.config);
  }

  withToken(token: string): CequreRealtimeClient {
    const cloned = Object.create(Object.getPrototypeOf(this));
    cloned.config = { ...this.config, token };
    cloned.client = this.client.withToken(token);
    cloned._subscriptions = new Map();
    cloned._activeChannels = new Map();
    cloned._cache = {};
    return cloned;
  }

  withHeaders(headers: ClientHeaders): CequreRealtimeClient {
    const cloned = Object.create(Object.getPrototypeOf(this));
    cloned.config = { ...this.config, headers };
    cloned.client = this.client.withHeaders(headers);
    cloned._subscriptions = new Map();
    cloned._activeChannels = new Map();
    cloned._cache = {};
    return cloned;
  }

  async queryCollection<T>(collection: string, params?: any): Promise<T[]> {
    const colNamespace = (this.client as any)[collection];
    if (!colNamespace || typeof colNamespace.get !== "function") {
      throw new Error(`Unknown collection "${collection}" on Cequre client`);
    }
    const res = await colNamespace.get(params);
    if (res.error) {
      throw new Error(res.error.message || `Failed to query ${collection}`);
    }
    const data = res.data;
    if (Array.isArray(data)) return data;
    if (data && Array.isArray(data.docs)) return data.docs;
    if (data && Array.isArray(data.items)) return data.items;
    return data ? [data] : [];
  }

  subscribeCollection<T>(
    collection: string,
    params: any,
    callback: (data: T[]) => void
  ): () => void {
    const queryKey = `${collection}:${JSON.stringify(params || {})}`;
    let sub = this._subscriptions.get(queryKey);

    if (!sub) {
      sub = {
        queryKey,
        collection,
        params,
        data: [],
        listeners: new Set(),
        initialized: false,
      };
      this._subscriptions.set(queryKey, sub);
    }

    sub.listeners.add(callback);

    if (sub.initialized) {
      try { callback(sub.data); } catch {}
    }

    this._ensureSubscription(sub);

    return () => {
      if (!sub) return;
      sub.listeners.delete(callback);
      if (sub.listeners.size === 0) {
        this._subscriptions.delete(queryKey);
        this._checkUnsubscribeChannel(collection);
      }
    };
  }

  private _ensureSubscription(sub: LiveQuerySubscription): void {
    this._ensureChannel(sub.collection);

    if (!sub.initialized && !sub.pendingPromise) {
      sub.pendingPromise = this.queryCollection(sub.collection, sub.params)
        .then((docs) => {
          sub.data = docs;
          sub.initialized = true;
          sub.pendingPromise = undefined;
          for (const listener of sub.listeners) {
            try { listener(sub.data); } catch {}
          }
          return docs;
        })
        .catch(() => {
          sub.pendingPromise = undefined;
          return [];
        });
    }
  }

  private async _ensureChannel(collection: string): Promise<void> {
    const existing = this._activeChannels.get(collection);
    if (existing) {
      existing.count++;
      return;
    }

    const channelEntry = {
      count: 1,
      unsubscribe: () => {},
    };
    this._activeChannels.set(collection, channelEntry);

    const onEvent = (event: any) => {
      this._handleStreamEvent(collection, event);
    };

    let unsubscribeHandler: () => void = () => {};
    try {
      if (this.config.transport === "sse") {
        unsubscribeHandler = await this.client.subscribeSSE(collection, onEvent);
      } else {
        unsubscribeHandler = await this.client.subscribeWS(collection, onEvent);
      }
      channelEntry.unsubscribe = unsubscribeHandler;
    } catch {
      // Fallback
    }
  }

  private _checkUnsubscribeChannel(collection: string): void {
    let stillNeeded = false;
    for (const sub of this._subscriptions.values()) {
      if (sub.collection === collection && sub.listeners.size > 0) {
        stillNeeded = true;
        break;
      }
    }
    if (!stillNeeded) {
      const channelEntry = this._activeChannels.get(collection);
      if (channelEntry) {
        try { channelEntry.unsubscribe(); } catch {}
        this._activeChannels.delete(collection);
      }
    }
  }

  private _handleStreamEvent(collection: string, rawEvent: any): void {
    if (!rawEvent) return;
    const event: StreamEvent = {
      id: rawEvent.id || String(Date.now()),
      collection: rawEvent.collection || collection,
      action: rawEvent.action || rawEvent.type || "updated",
      data: rawEvent.data !== undefined ? rawEvent.data : rawEvent,
      timestamp: rawEvent.timestamp || Date.now(),
    };

    const item = event.data;
    if (!item || typeof item !== "object" || !("id" in item)) return;
    const action = String(event.action || "").toLowerCase();

    for (const sub of this._subscriptions.values()) {
      if (sub.collection !== collection) continue;
      let changed = false;

      if (action === "created" || action === "create" || action === "post") {
        if (this._matchesWhere(item, sub.params?.query?.where || sub.params?.where)) {
          const existingIdx = sub.data.findIndex((x: any) => x.id === item.id);
          if (existingIdx !== -1) {
            sub.data[existingIdx] = { ...sub.data[existingIdx], ...item };
          } else {
            const optIdx = sub.data.findIndex((x: any) => typeof x.id === "string" && x.id.startsWith("_opt_"));
            if (optIdx !== -1 && !String(item.id).startsWith("_opt_")) {
              sub.data[optIdx] = item;
            } else {
              sub.data = [...sub.data, item];
            }
          }
          sub.data = this._sortItems(sub.data, sub.params?.query?.sort || sub.params?.sort);
          changed = true;
        }
      } else if (action === "updated" || action === "update" || action === "patch" || action === "put") {
        const idx = sub.data.findIndex((x: any) => x.id === item.id);
        const matches = this._matchesWhere(item, sub.params?.query?.where || sub.params?.where);
        if (matches) {
          if (idx !== -1) {
            sub.data[idx] = { ...sub.data[idx], ...item };
          } else {
            sub.data = [...sub.data, item];
          }
          sub.data = this._sortItems(sub.data, sub.params?.query?.sort || sub.params?.sort);
          changed = true;
        } else if (idx !== -1) {
          sub.data = sub.data.filter((x: any) => x.id !== item.id);
          changed = true;
        }
      } else if (action === "deleted" || action === "delete") {
        const targetId = typeof item === "object" ? item.id : item;
        const idx = sub.data.findIndex((x: any) => x.id === targetId);
        if (idx !== -1) {
          sub.data = sub.data.filter((x: any) => x.id !== targetId);
          changed = true;
        }
      }

      if (changed) {
        sub.lastEventId = event.id;
        for (const listener of sub.listeners) {
          try { listener([...sub.data]); } catch {}
        }
      }
    }
  }

  private _matchesWhere(item: any, where?: any): boolean {
    if (!item || typeof item !== "object") return false;
    if (!where || typeof where !== "object" || Object.keys(where).length === 0) return true;

    for (const [key, condition] of Object.entries(where)) {
      if (key === "and" || key === "$and") {
        if (Array.isArray(condition)) {
          if (!condition.every((c: any) => this._matchesWhere(item, c))) return false;
        }
        continue;
      }
      if (key === "or" || key === "$or") {
        if (Array.isArray(condition)) {
          if (!condition.some((c: any) => this._matchesWhere(item, c))) return false;
        }
        continue;
      }

      const val = item[key];

      if (condition !== null && typeof condition === "object" && !Array.isArray(condition)) {
        if ("equals" in condition && val !== (condition as any).equals) return false;
        if ("notEquals" in condition && val === (condition as any).notEquals) return false;
        if ("contains" in condition && !String(val ?? "").toLowerCase().includes(String((condition as any).contains).toLowerCase())) return false;
        if ("in" in condition && Array.isArray((condition as any).in) && !(condition as any).in.includes(val)) return false;
        if ("notIn" in condition && Array.isArray((condition as any).notIn) && (condition as any).notIn.includes(val)) return false;
        if ("greaterThan" in condition && !(val > (condition as any).greaterThan)) return false;
        if ("greaterThanOrEqual" in condition && !(val >= (condition as any).greaterThanOrEqual)) return false;
        if ("lessThan" in condition && !(val < (condition as any).lessThan)) return false;
        if ("lessThanOrEqual" in condition && !(val <= (condition as any).lessThanOrEqual)) return false;
      } else {
        if (val !== condition) return false;
      }
    }

    return true;
  }

  private _sortItems(items: any[], sort?: any): any[] {
    if (!sort || items.length <= 1) return items;
    const copy = [...items];
    let field = "";
    let direction = 1;

    if (typeof sort === "string") {
      if (sort.startsWith("-")) {
        direction = -1;
        field = sort.slice(1);
      } else {
        field = sort;
      }
    } else if (typeof sort === "object") {
      const entries = Object.entries(sort);
      if (entries.length > 0) {
        field = entries[0][0];
        const dirStr = String(entries[0][1]).toLowerCase();
        direction = dirStr === "desc" || dirStr === "-1" ? -1 : 1;
      }
    }

    if (!field) return copy;

    return copy.sort((a, b) => {
      const valA = a[field];
      const valB = b[field];
      if (valA === valB) return 0;
      if (valA === undefined || valA === null) return 1;
      if (valB === undefined || valB === null) return -1;
      if (valA < valB) return -1 * direction;
      return 1 * direction;
    });
  }

  async mutateCreate<T, Input>(
    collection: string,
    data: Input,
    serverCall: () => Promise<SDKResponse<T>>
  ): Promise<T> {
    const tempId = `_opt_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    const optimisticDoc = {
      id: tempId,
      ...(data as any),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    this._handleStreamEvent(collection, {
      id: tempId,
      collection,
      action: "created",
      data: optimisticDoc,
      timestamp: Date.now(),
    });

    try {
      const res = await serverCall();
      if (res.error || !res.data) {
        throw new Error(res.error?.message || `Failed to create in ${collection}`);
      }
      this._reconcileOptimistic(collection, tempId, res.data);
      return res.data;
    } catch (err) {
      this._handleStreamEvent(collection, {
        id: tempId,
        collection,
        action: "deleted",
        data: { id: tempId },
        timestamp: Date.now(),
      });
      throw err;
    }
  }

  async mutatePatch<T, Input>(
    collection: string,
    id: string,
    data: Input,
    serverCall: () => Promise<SDKResponse<T>>
  ): Promise<T> {
    const backupDocs = new Map<string, any>();
    for (const [key, sub] of this._subscriptions) {
      if (sub.collection === collection) {
        const existing = sub.data.find((x: any) => x.id === id);
        if (existing) backupDocs.set(key, { ...existing });
      }
    }

    this._handleStreamEvent(collection, {
      id: String(Date.now()),
      collection,
      action: "updated",
      data: { id, ...(data as any) },
      timestamp: Date.now(),
    });

    try {
      const res = await serverCall();
      if (res.error || !res.data) {
        throw new Error(res.error?.message || `Failed to patch ${id} in ${collection}`);
      }
      this._handleStreamEvent(collection, {
        id: String(Date.now()),
        collection,
        action: "updated",
        data: res.data,
        timestamp: Date.now(),
      });
      return res.data;
    } catch (err) {
      for (const [key, oldDoc] of backupDocs) {
        const sub = this._subscriptions.get(key);
        if (sub) {
          const idx = sub.data.findIndex((x: any) => x.id === id);
          if (idx !== -1) sub.data[idx] = oldDoc;
          for (const listener of sub.listeners) {
            try { listener([...sub.data]); } catch {}
          }
        }
      }
      throw err;
    }
  }

  async mutateDelete(
    collection: string,
    id: string,
    serverCall: () => Promise<SDKResponse<any>>
  ): Promise<void> {
    const backupDocs = new Map<string, any>();
    for (const [key, sub] of this._subscriptions) {
      if (sub.collection === collection) {
        const existing = sub.data.find((x: any) => x.id === id);
        if (existing) backupDocs.set(key, { ...existing });
      }
    }

    this._handleStreamEvent(collection, {
      id: String(Date.now()),
      collection,
      action: "deleted",
      data: { id },
      timestamp: Date.now(),
    });

    try {
      const res = await serverCall();
      if (res.error) {
        throw new Error(res.error.message || `Failed to delete ${id} in ${collection}`);
      }
    } catch (err) {
      for (const [key, oldDoc] of backupDocs) {
        const sub = this._subscriptions.get(key);
        if (sub) {
          sub.data = [...sub.data, oldDoc];
          sub.data = this._sortItems(sub.data, sub.params?.query?.sort || sub.params?.sort);
          for (const listener of sub.listeners) {
            try { listener([...sub.data]); } catch {}
          }
        }
      }
      throw err;
    }
  }

  private _reconcileOptimistic(collection: string, tempId: string, serverDoc: any): void {
    for (const sub of this._subscriptions.values()) {
      if (sub.collection !== collection) continue;
      const optIdx = sub.data.findIndex((x: any) => x.id === tempId);
      const realIdx = sub.data.findIndex((x: any) => x.id === serverDoc.id);

      if (optIdx !== -1) {
        if (realIdx !== -1 && realIdx !== optIdx) {
          sub.data.splice(optIdx, 1);
        } else {
          if (this._matchesWhere(serverDoc, sub.params?.query?.where || sub.params?.where)) {
            sub.data[optIdx] = serverDoc;
            sub.data = this._sortItems(sub.data, sub.params?.query?.sort || sub.params?.sort);
          } else {
            sub.data.splice(optIdx, 1);
          }
        }
        for (const listener of sub.listeners) {
          try { listener([...sub.data]); } catch {}
        }
      } else if (realIdx === -1) {
        if (this._matchesWhere(serverDoc, sub.params?.query?.where || sub.params?.where)) {
          sub.data = this._sortItems([...sub.data, serverDoc], sub.params?.query?.sort || sub.params?.sort);
          for (const listener of sub.listeners) {
            try { listener([...sub.data]); } catch {}
          }
        }
      }
    }
  }

  async syncDurableStream(collection: string): Promise<void> {
    let oldestLastEventId: string | undefined;
    for (const sub of this._subscriptions.values()) {
      if (sub.collection === collection && sub.lastEventId) {
        if (!oldestLastEventId || sub.lastEventId < oldestLastEventId) {
          oldestLastEventId = sub.lastEventId;
        }
      }
    }

    if (!oldestLastEventId) return;

    try {
      const res = await this.client.request<StreamEvent[]>(
        'GET',
        `${this.prefix}/${collection}/stream?lastEventId=${encodeURIComponent(oldestLastEventId)}`
      );
      if (res.data && Array.isArray(res.data)) {
        for (const evt of res.data) {
          this._handleStreamEvent(collection, evt);
        }
      }
    } catch {
      // Graceful fallback
    }
  }
}


